Here's a complete checkout screen for a Telegram Mini App — a `CheckoutScreen.tsx` component plus its `CheckoutScreen.css`. It lists cart items with a total, has a validated delivery address form, wires up the Telegram `BackButton` (falling back to a plain back link), and a `Pay` button that calls back to the parent with the collected address.

```tsx
// CheckoutScreen.tsx
import React, { useEffect, useMemo, useState } from 'react';
import './CheckoutScreen.css';

export interface CartItem {
  id: string;
  title: string;
  price: number; // minor units avoided on purpose — plain decimal, formatted for display
  quantity: number;
  imageUrl?: string;
}

export interface DeliveryAddress {
  fullName: string;
  phone: string;
  city: string;
  street: string;
  apartment: string;
  postalCode: string;
  comment: string;
}

export interface CheckoutScreenProps {
  items: CartItem[];
  currency?: string; // e.g. "USD", "EUR" — defaults to "USD"
  initialAddress?: Partial<DeliveryAddress>;
  onBack: () => void;
  onPay: (address: DeliveryAddress, total: number) => Promise<void> | void;
}

type FormErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  apartment: '',
  postalCode: '',
  comment: '',
};

function formatMoney(amount: number, currency: string): string {
  try {
    return new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency,
      minimumFractionDigits: 2,
    }).format(amount);
  } catch {
    return `${amount.toFixed(2)} ${currency}`;
  }
}

function validate(address: DeliveryAddress): FormErrors {
  const errors: FormErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = 'Enter your full name';
  }

  const digits = address.phone.replace(/[^\d+]/g, '');
  if (!digits || digits.replace('+', '').length < 7) {
    errors.phone = 'Enter a valid phone number';
  }

  if (!address.city.trim()) {
    errors.city = 'Enter a city';
  }

  if (!address.street.trim()) {
    errors.street = 'Enter a street address';
  }

  if (!address.postalCode.trim()) {
    errors.postalCode = 'Enter a postal code';
  }

  return errors;
}

export default function CheckoutScreen({
  items,
  currency = 'USD',
  initialAddress,
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>({
    ...EMPTY_ADDRESS,
    ...initialAddress,
  });
  const [errors, setErrors] = useState<FormErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isPaying, setIsPaying] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const deliveryFee = items.length > 0 ? 4.99 : 0;
  const total = subtotal + deliveryFee;

  // Wire up Telegram's native back button when running inside Telegram.
  useEffect(() => {
    const tg = window.Telegram?.WebApp;
    if (!tg?.BackButton) return;

    tg.BackButton.show();
    tg.BackButton.onClick(onBack);

    return () => {
      tg.BackButton.offClick(onBack);
      tg.BackButton.hide();
    };
  }, [onBack]);

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    setAddress((prev) => ({ ...prev, [field]: e.target.value }));
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validate({ ...address }));
  };

  const handlePay = async (e: React.FormEvent) => {
    e.preventDefault();
    const nextErrors = validate(address);
    setErrors(nextErrors);
    setTouched({
      fullName: true,
      phone: true,
      city: true,
      street: true,
      apartment: true,
      postalCode: true,
      comment: true,
    });

    if (Object.keys(nextErrors).length > 0) {
      window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred('error');
      return;
    }

    setPayError(null);
    setIsPaying(true);
    try {
      await onPay(address, total);
      window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred('success');
    } catch (err) {
      setPayError(err instanceof Error ? err.message : 'Payment failed. Please try again.');
      window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred('error');
    } finally {
      setIsPaying(false);
    }
  };

  const fieldError = (field: keyof DeliveryAddress) =>
    touched[field] ? errors[field] : undefined;

  return (
    <div className="checkout-screen">
      <header className="checkout-header">
        <button
          type="button"
          className="checkout-back-button"
          onClick={onBack}
          aria-label="Back to cart"
        >
          <span className="checkout-back-arrow" aria-hidden="true">
            ‹
          </span>
          Back to cart
        </button>
        <h1 className="checkout-title">Checkout</h1>
      </header>

      <section className="checkout-section" aria-labelledby="checkout-items-heading">
        <h2 id="checkout-items-heading" className="checkout-section-title">
          Your order
        </h2>

        {items.length === 0 ? (
          <p className="checkout-empty">Your cart is empty.</p>
        ) : (
          <ul className="checkout-items">
            {items.map((item) => (
              <li className="checkout-item" key={item.id}>
                <div className="checkout-item-thumb">
                  {item.imageUrl ? (
                    <img src={item.imageUrl} alt="" />
                  ) : (
                    <span className="checkout-item-thumb-fallback" aria-hidden="true">
                      {item.title.charAt(0).toUpperCase()}
                    </span>
                  )}
                </div>
                <div className="checkout-item-info">
                  <span className="checkout-item-title">{item.title}</span>
                  <span className="checkout-item-qty">Qty {item.quantity}</span>
                </div>
                <span className="checkout-item-price">
                  {formatMoney(item.price * item.quantity, currency)}
                </span>
              </li>
            ))}
          </ul>
        )}

        <dl className="checkout-summary">
          <div className="checkout-summary-row">
            <dt>Subtotal</dt>
            <dd>{formatMoney(subtotal, currency)}</dd>
          </div>
          <div className="checkout-summary-row">
            <dt>Delivery</dt>
            <dd>{formatMoney(deliveryFee, currency)}</dd>
          </div>
          <div className="checkout-summary-row checkout-summary-total">
            <dt>Total</dt>
            <dd>{formatMoney(total, currency)}</dd>
          </div>
        </dl>
      </section>

      <form className="checkout-section checkout-form" onSubmit={handlePay} noValidate>
        <h2 className="checkout-section-title">Delivery address</h2>

        <div className="checkout-field">
          <label htmlFor="fullName">Full name</label>
          <input
            id="fullName"
            type="text"
            autoComplete="name"
            value={address.fullName}
            onChange={handleChange('fullName')}
            onBlur={handleBlur('fullName')}
            className={fieldError('fullName') ? 'checkout-input-error' : undefined}
          />
          {fieldError('fullName') && (
            <span className="checkout-field-error">{fieldError('fullName')}</span>
          )}
        </div>

        <div className="checkout-field">
          <label htmlFor="phone">Phone number</label>
          <input
            id="phone"
            type="tel"
            autoComplete="tel"
            value={address.phone}
            onChange={handleChange('phone')}
            onBlur={handleBlur('phone')}
            className={fieldError('phone') ? 'checkout-input-error' : undefined}
          />
          {fieldError('phone') && (
            <span className="checkout-field-error">{fieldError('phone')}</span>
          )}
        </div>

        <div className="checkout-field-row">
          <div className="checkout-field">
            <label htmlFor="city">City</label>
            <input
              id="city"
              type="text"
              autoComplete="address-level2"
              value={address.city}
              onChange={handleChange('city')}
              onBlur={handleBlur('city')}
              className={fieldError('city') ? 'checkout-input-error' : undefined}
            />
            {fieldError('city') && (
              <span className="checkout-field-error">{fieldError('city')}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="postalCode">Postal code</label>
            <input
              id="postalCode"
              type="text"
              autoComplete="postal-code"
              value={address.postalCode}
              onChange={handleChange('postalCode')}
              onBlur={handleBlur('postalCode')}
              className={fieldError('postalCode') ? 'checkout-input-error' : undefined}
            />
            {fieldError('postalCode') && (
              <span className="checkout-field-error">{fieldError('postalCode')}</span>
            )}
          </div>
        </div>

        <div className="checkout-field">
          <label htmlFor="street">Street address</label>
          <input
            id="street"
            type="text"
            autoComplete="address-line1"
            value={address.street}
            onChange={handleChange('street')}
            onBlur={handleBlur('street')}
            className={fieldError('street') ? 'checkout-input-error' : undefined}
          />
          {fieldError('street') && (
            <span className="checkout-field-error">{fieldError('street')}</span>
          )}
        </div>

        <div className="checkout-field">
          <label htmlFor="apartment">Apartment / suite (optional)</label>
          <input
            id="apartment"
            type="text"
            autoComplete="address-line2"
            value={address.apartment}
            onChange={handleChange('apartment')}
          />
        </div>

        <div className="checkout-field">
          <label htmlFor="comment">Delivery notes (optional)</label>
          <textarea
            id="comment"
            rows={3}
            value={address.comment}
            onChange={handleChange('comment')}
          />
        </div>

        {payError && <p className="checkout-pay-error">{payError}</p>}

        <button
          type="submit"
          className="checkout-pay-button"
          disabled={isPaying || items.length === 0}
        >
          {isPaying ? 'Processing…' : `Pay ${formatMoney(total, currency)}`}
        </button>
      </form>
    </div>
  );
}

declare global {
  interface Window {
    Telegram?: {
      WebApp?: {
        BackButton?: {
          show: () => void;
          hide: () => void;
          onClick: (cb: () => void) => void;
          offClick: (cb: () => void) => void;
        };
        HapticFeedback?: {
          notificationOccurred: (type: 'error' | 'success' | 'warning') => void;
        };
      };
    };
  }
}
```

